<?php
session_start();
require_once __DIR__ . '/../includes/role_helpers.php';
requireAnyRole(['supplier']);
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/supplier_account.php';
$userId=(int)$_SESSION['user_id'];$profile=ensureSupplierProfile($conn,$userId,$_SESSION['name']??'Supplier');$supplierId=(int)$profile['id'];
$stmt=$conn->prepare("SELECT p.id,p.product_name,p.cost_price,p.selling_price,p.stock_quantity,p.minimum_stock,p.status,c.category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.supplier_id=? ORDER BY p.product_name");$stmt->bind_param('i',$supplierId);$stmt->execute();$products=$stmt->get_result();
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Supplier Products</title><style>*{box-sizing:border-box;font-family:Arial,sans-serif}body{margin:0;min-height:100vh;color:#fff;background:#121426}.wrap{max-width:1180px;margin:auto;padding:34px 22px}.panel{background:#262740;border:1px solid #3c3e62;border-radius:16px;padding:22px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px}.top p{color:#b8bdd6}.btn{display:inline-block;text-decoration:none;padding:10px 14px;border-radius:9px;background:linear-gradient(135deg,#c06ceb,#5df09d);color:#17182c;font-weight:900}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid rgba(255,255,255,.08);text-align:left}th{background:#202036;color:#d7daea}.low{color:#ffd479;font-weight:800}.ok{color:#5df09d;font-weight:800}@media(max-width:760px){.panel{overflow:auto}.top{align-items:flex-start;flex-direction:column}}</style></head><body><?php include __DIR__.'/nav.php'; ?><main class="wrap"><section class="panel"><div class="top"><div><h1 style="margin:0 0 7px">Assigned Products</h1><p style="margin:0">Only products assigned to your Supplier profile appear here.</p></div><a class="btn" href="/smart_inventory/supplier/supply.php">Supply Stock</a></div><table><thead><tr><th>Product</th><th>Category</th><th>Cost</th><th>Current Stock</th><th>Minimum</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if($products->num_rows): while($p=$products->fetch_assoc()): $isLow=(int)$p['stock_quantity']<=(int)$p['minimum_stock']; ?><tr><td><?php echo htmlspecialchars($p['product_name']); ?></td><td><?php echo htmlspecialchars($p['category_name']??'Uncategorized'); ?></td><td>₱<?php echo number_format((float)$p['cost_price'],2); ?></td><td class="<?php echo $isLow?'low':'ok'; ?>"><?php echo (int)$p['stock_quantity']; ?></td><td><?php echo (int)$p['minimum_stock']; ?></td><td><?php echo htmlspecialchars(strtoupper($p['status'])); ?></td><td><a class="btn" style="padding:7px 10px" href="/smart_inventory/supplier/supply.php?product_id=<?php echo (int)$p['id']; ?>">Supply</a></td></tr><?php endwhile; else: ?><tr><td colspan="7" style="text-align:center;color:#b8bdd6">No products are assigned to this supplier yet. Ask the administrator to assign products to your Supplier profile.</td></tr><?php endif; ?></tbody></table></section></main></body></html>
